CREATE TABLE entities(id TEXT PRIMARY KEY,kind TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX entities_kind ON entities(kind,status,updated DESC,id);
CREATE TABLE entity_revisions(entity TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,actor TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(entity,revision));
CREATE TABLE assistant_clients(id TEXT PRIMARY KEY,name TEXT NOT NULL,scopes TEXT NOT NULL,redirects TEXT NOT NULL DEFAULT '[]',expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE assistant_tokens(digest TEXT PRIMARY KEY,client TEXT NOT NULL REFERENCES assistant_clients(id),scopes TEXT NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE oauth_codes(digest TEXT PRIMARY KEY,client TEXT NOT NULL,redirect TEXT NOT NULL,challenge TEXT NOT NULL,scopes TEXT NOT NULL,resource TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE admin_sessions(digest TEXT PRIMARY KEY,csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE platform_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,tool TEXT NOT NULL,target TEXT NOT NULL,outcome TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE idempotency(actor TEXT NOT NULL,key TEXT NOT NULL,fingerprint TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(actor,key));
CREATE TABLE change_plans(id TEXT PRIMARY KEY,actor TEXT NOT NULL,tool TEXT NOT NULL,args TEXT NOT NULL,fingerprint TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE thread_controls(post TEXT PRIMARY KEY REFERENCES posts(id),locked INTEGER NOT NULL DEFAULT 0,staff INTEGER NOT NULL DEFAULT 0);
CREATE TABLE jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,due INTEGER NOT NULL,result TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX jobs_due ON jobs(state,due);
CREATE TABLE media_uploads(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL,mime TEXT NOT NULL,expires INTEGER NOT NULL,uploaded INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audience(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,consent INTEGER NOT NULL DEFAULT 0,suppressed INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE analytics_daily(day TEXT NOT NULL,path TEXT NOT NULL,source TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(day,path,source));
CREATE TABLE webhook_deliveries(id TEXT PRIMARY KEY,event TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL);
